p=Path('game/app.mjs');s=p.read_text(encoding='utf-8');s=s.replace('<div class="row"><div><b>${nameOf(u.type)}</b>', '<div class="row civilian-row"><span aria-hidden="true" class="civilian-portrait" style="--portrait:${({builder:0,engineer:1,explorer:2,merchant:3,spy:4,railBuilder:1})[u.type]??0}"></span><div><b>${nameOf(u.type)}</b>',1);p.write_text(s,encoding='utf-8')
